def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data.get("roots", {})
        choices = []
        for name in names:
            choices.append([None] + [row for row in packages[name]
                                     if row["version"] not in blocked.get(name, [])
                                     and (name not in pins or row["version"] == pins[name])])

        best_key = None
        best = None
        for selection in product(*choices):
            rows = {name: row for name, row in zip(names, selection) if row is not None}
            if any(name not in rows or not low <= rows[name]["version"] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in rows}
            valid = True
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    edges[name].append(other)
                    if (other not in rows or
                            not dep["min"] <= rows[other]["version"] <= dep["max"]):
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            # Installed packages must be exactly the roots' active dependency closure.
            closure = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in closure:
                    continue
                if name not in rows:
                    valid = False
                    break
                closure.add(name)
                pending.extend(edges[name])
            if not valid or closure != set(rows):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in rows):
                continue

            key = tuple(rows[name]["version"] if name in rows else -1
                        for name in reversed(names))
            if best_key is None or key < best_key:
                best_key = key
                best = {name: rows[name]["version"] for name in rows}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        available = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(available, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[j]["start"]
                   for i in range(len(ordered)) for j in range(i + 1, len(ordered))):
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value, best_ids = value, selected
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = required_bit.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], data["coupons"], initial_mask)
        dist = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        while queue:
            time, node, left, mask = heapq.heappop(queue)
            state = (node, left, mask)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and left == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], left)]
                if left:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
                for duration, next_left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bit.get(next_node, 0)
                    next_state = (next_node, next_left, next_mask)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival,) + next_state)
        return {"arrival": None}
    return solve


